    $rootBinding=Get-MbacrProducerRootBinding 'pc-install' $Root;$pb=Get-MbacrProducerBinding $rootBinding $producerArgs;$vb=Get-MbacrValidatorBinding $rootBinding $validatorArgs;$argsHash=Get-MbacrProducerStructuredHash 'mbacr/locator-arguments/1' @($producerArgs,$validatorArgs);$to02=('a'*64)
