    $attempt=[pscustomobject][ordered]@{schemaVersion='cerg-mbacr-locator-attempt/1.1.0';artifactId='MBACR-A00';contractHeadCommit=('b'*40);to02Sha256=$to02;locatorAuthorization=$auth;sourceRootBinding=$rootBinding;producerBinding=$pb;validatorBinding=$vb;selectorPlan=@($selectors|ForEach-Object{[pscustomobject][ordered]@{selectorId=$_.selectorId;sourceId=$_.sourceId;portableRelativePath=$_.portableRelativePath}});allowanceUsedBeforeInstall=0;allowanceUsedAfterInstall=1;status='ArmedNoSourceOpen';nextAction='RunExactFourLocatorOpens'}
